L2_1.m_Talk_KOREA = "지진도, 마물들이 마을에 계속 나타나는 것도 이상했어. 뭔가 이상했다고!"
L2_1.m_fTalkTime = 0.03
L2_1.m_Talk_JPN = "地震も、魔物どもが村に現れるようになったのも、なにか怪しいと思っていた。やっぱりそうだったんだ！"
L2_1.m_Talk_ENG = "The earthquakes and monsters invading the village. I know something was off!"
L2_1.m_Talk_TWN = "地震也好，不斷出現在村子裡的怪物也好，都很不尋常。一定有什麼不對勁！"
L2_1.m_Talk_SCN = "地震也好，不断出现在村子里的魔物也好，都很诡异。一定有什么不对劲！"
L2_1.m_Talk_DEU = "The earthquakes and monsters invading the village. I know something was off!"
L2_1.m_Talk_FRA = "The earthquakes and monsters invading the village. I know something was off!"
L3_1 = {}
L3_1.m_CutScenKey_Talk = "AVENGER_ACT2_INTERLUDE3@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 6600203
L3_1.m_CutScenStrID = "AVENGER_ACT2_INTERLUDE3"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "CITIZEN_ROOT_NPC_NULL"
L3_1.m_Talk_KOREA = "어쩐지 최근 들어 안 좋은 징조가 너무 많았어요! 결국 종말의 예언처럼 세상이 끝나려는 거라고요!"
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "最近は不穏な出来事が多すぎたわ！　まるで終末の予言通り、世界が終わろうとしているかのように！"
L3_1.m_Talk_ENG = "No wonder there were so many omens recently! The world is going to end just like it said in the Apocalypse Augury!"
L3_1.m_Talk_TWN = "難怪最近怪事這麼多！是末日的預言要成真了嗎！"
L3_1.m_Talk_SCN = "最近不祥的预兆也太多了！世界要像末日预言的那样终结了吗！"
L3_1.m_Talk_DEU = "No wonder there were so many omens recently! The world is going to end just like it said in the Apocalypse Augury!"
L3_1.m_Talk_FRA = "No wonder there were so many omens recently! The world is going to end just like it said in the Apocalypse Augury!"
