L31_1.m_CutScenStrID = "AVENGER_ACT2_INTERLUDE3"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Talk_KOREA = "자길 속였다고 생각할 거예요. 낙인에 대해 말할 기회가 있었는데도, 말하지 않았으니까."
L31_1.m_fTalkTime = 0.03
L31_1.m_Talk_JPN = "自分は騙されたと思っているでしょう。烙印について話す機会があったのに、言わなかったのだから。"
L31_1.m_Talk_ENG = "I'm sure she's thinking that I fooled her. Because even though I had a chance to tell her about the mark, I didn't."
L31_1.m_Talk_TWN = "一定是覺得我欺騙了她…明明有機會和她說明的…"
L31_1.m_Talk_SCN = "一定是觉得我欺骗了她……明明有机会和她说明的……"
L31_1.m_Talk_DEU = "I'm sure she's thinking that I fooled her. Because even though I had a chance to tell her about the mark, I didn't."
L31_1.m_Talk_FRA = "I'm sure she's thinking that I fooled her. Because even though I had a chance to tell her about the mark, I didn't."
