L8_1 = "뭐? 너 어른들이 한 말 잊었어? 동토에서 살아있는 사람을 발견한 것 자체가 말도 안 되는 일이라고!"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "はあ？　お前、大人たちが言ってたことを聞いていなかったか？　凍土で生きてる人間がいること自体あり得ないことなんだよ！"
L7_1.m_Talk_JPN = L8_1
L8_1 = "What? Did you forget what the adults told us? It's impossible to find a living person out in the gelid lands in the first place!"
L7_1.m_Talk_ENG = L8_1
L8_1 = "什麼？你忘了大人說的話嗎？凍土上怎麼可能會有活人！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "什么？你忘了大人们说的话吗？冻土上怎么可能会有活人！"
